def decide(recipient_reputation, round_num, my_history):
    # Base threshold depends on round number (more cautious early, more generous later)
    if round_num < 5:
        threshold = 2.0
    elif round_num < 15:
        threshold = 1.0
    else:
        threshold = 0.5
    # Adapt threshold based on how often I was defected recently (last 5 rounds)
    recent_defections = 0
    for entry in my_history[-5:]:
        if entry['partner_action'] != 'donate':
            recent_defections += 1
    # If frequently defected, raise threshold to become more cautious
    if recent_defections >= 3:
        threshold += 1.5
    # If rarely defected, lower threshold to become more generous
    if recent_defections <= 1 and len(my_history) >= 3:
        threshold = max(0.0, threshold - 0.5)
    # Plus: if I have donated in the last round, be slightly more generous
